{"input": "Module[{byte1Seed = {1, 4}, byte1Seq, twinPrimes, isPrime, bbpDelta, limit = 5000, n = 3, pidHistory = {}, hTarget = 0.35, kp = 1.2, ki = 0.3, kd = 0.1, error = 0, errorSum = 0, lastError = 0, collapsePoints = {}, hFunction},

  (* Byte1 sequence generator *)
  byte1Seq = NestList[
    Function[{pair},
      Module[{diff = Abs[pair[[-1]] - pair[[-2]]], len},
        len = IntegerLength[diff, 2];
        Append[pair, len]
      ]
    ], byte1Seed, 50][[-1]];

  (* Prime checker *)
  isPrime[n_] := PrimeQ[n];

  (* BBP-based delta step *)
  bbpDelta[n_] := Floor[Total[Table[16^(1 - k)/(8 k + Mod[n, 7] + 1), {k, 1, 4}]]] + 1;

  (* Generate twin primes with BBP skip *)
  twinPrimes = Reap[
    While[n < limit,
      If[isPrime[n] && isPrime[n + 2], Sow[{n, n + 2}]];
      n += bbpDelta[n];
    ]
  ][[2, 1]];

  (* Define H(t) as match ratio to Byte1 pattern *)
  hFunction[tp_] := Module[{digits = IntegerDigits[tp[[1]], 10], overlap, match},
    overlap = Take[byte1Seq, Length[digits]];
    match = Count[MapThread[Equal, {digits, overlap}], True];
    N[match/Length[digits]]
  ];

  (* PID-regulated collapse detection *)
  Do[
    Module[{h = hFunction[pair], deltaH, pidOutput},
      deltaH = Abs[h - hTarget];
      errorSum += deltaH;
      pidOutput = -kp*deltaH - ki*errorSum - kd*(deltaH - lastError);
      lastError = deltaH;
      If[Abs[pidOutput] < 0.05, AppendTo[collapsePoints, pair]];
    ],
    {pair, twinPrimes}
  ];

  ListPlot[
    Map[{Mean[#], 1} &, collapsePoints],
    PlotStyle -> {Red, PointSize[Medium]},
    AxesLabel -> {"Twin Prime Midpoint", "Collapse"},
    PlotRange -> All,
    PlotMarkers -> Automatic
  ]
]"}

