{"input": "Module[{byte1Seed = {1, 4}, byte1Seq, twinPrimes, isPrime, bbpDelta, limit = 5000, n = 3, hTarget = 0.35, collapsePoints = {}, hScores = {}, hFunctionBase2},

  (* Extended Byte1 sequence using recursion *)
  byte1Seq = NestList[
    Function[{pair},
      Module[{diff = Abs[pair[[-1]] - pair[[-2]]], len},
        len = IntegerLength[diff, 2];
        Append[pair, len]
      ]
    ], byte1Seed, 300][[-1]];

  (* Prime checker *)
  isPrime[n_] := PrimeQ[n];

  (* BBP-style harmonic skip *)
  bbpDelta[n_] := Floor[Total[Table[16^(1 - k)/(8 k + Mod[n, 7] + 1), {k, 1, 4}]]] + 1;

  (* Generate BBP twin primes *)
  twinPrimes = Reap[
    While[n < limit,
      If[isPrime[n] && isPrime[n + 2], Sow[{n, n + 2}]];
      n += bbpDelta[n];
    ]
  ][[2, 1]];

  (* Base-2 H(t): match ratio of binary digits vs Byte1 sequence *)
  hFunctionBase2[tp_] := Module[{digits, overlap, match},
    digits = IntegerDigits[tp[[1]], 2];
    overlap = Take[byte1Seq, Length[digits]];
    match = Count[MapThread[Equal, {digits, overlap}], True];
    N[match/Length[digits]]
  ];

  (* Score each twin prime *)
  Do[
    Module[{h = hFunctionBase2[pair]},
      AppendTo[hScores, {Mean[pair], h}];
      If[Abs[h - hTarget] < 0.15, AppendTo[collapsePoints, {Mean[pair], 1}]];
    ],
    {pair, twinPrimes}
  ];

  Show[
    ListPlot[hScores, PlotStyle -> Blue, AxesLabel -> {"Twin Prime Midpoint", "H(t) Match Score"}],
    ListPlot[collapsePoints, PlotStyle -> {Red, PointSize[Medium]}]
  ]
]"}

