(* Recursive Harmonic TSP Heuristic with Phase Echo Layer *)

ClearAll[solveRHATSP];

solveRHATSP[cityData_, H0_: 0.35, maxIter_: 50] := Module[
  {
    n = Length[cityData],
    dist, curvature, totalCost, totalDistance, totalCurvature,
    tour, improved, i, j, newTour, newCost, currentCost, iter = 0,
    bearing, curvatureAt, alphaFade = 0.9, echoMemory = {},
    H = H0, R, deltaTheta, deltaL, resonanceEnergy
  },

  (* Great-circle distance (haversine) *)
  dist[i_, j_] := GeoDistance[cityData[[i]], cityData[[j]]][[1]];

  (* Curvature at a point via bearings *)
  bearing[p1_, p2_] := GeoBearing[cityData[[p1]], cityData[[p2]]];

  curvatureAt[i_] := Module[{b1, b2, angle},
    b1 = bearing[tour[[Mod[i - 2, n] + 1]], tour[[i]]];
    b2 = bearing[tour[[i]], tour[[Mod[i, n] + 1]]];
    angle = Abs[AngleVector[{1, 0}, AngleVector[b2 - b1]]];
    angle
  ];

  totalDistance[tr_] := Total[Table[dist[tr[[k]], tr[[Mod[k, n] + 1]]], {k, 1, n}]];

  totalCurvature[tr_] := Total[Table[curvatureAt[k], {k, 1, n}]];

  totalCost[tr_] := totalDistance[tr] + H * totalCurvature[tr];

  tour = Range[n];
  tour = RandomSample[tour];
  currentCost = totalCost[tour];
  AppendTo[echoMemory, tour];

  While[iter < maxIter,
    improved = False;
    For[i = 1, i <= n - 2, i++,
      For[j = i + 2, j <= n, j++,
        newTour = Join[Take[tour, i], Reverse[Take[tour, {i + 1, j}]], Drop[tour, j]];
        newCost = totalCost[newTour];
        If[newCost < currentCost,
          tour = newTour;
          currentCost = newCost;
          AppendTo[echoMemory, tour];
          improved = True;
          Break[];
        ];
      ];
      If[improved, Break[]];
    ];

    (* Phase echo update *)
    If[Length[echoMemory] >= 2,
      deltaTheta = totalCurvature[echoMemory[[-1]]] - totalCurvature[echoMemory[[-2]]];
      deltaL = totalDistance[echoMemory[[-1]]] - totalDistance[echoMemory[[-2]]];
      R = If[deltaL != 0, deltaTheta/deltaL, 0];
      resonanceEnergy = Abs[R];
      H = alphaFade * H + (1 - alphaFade) * resonanceEnergy;
    ];

    iter++;
    If[Not[improved], Break[]];
  ];

  <|
    "Tour" -> tour,
    "NamedTour" -> Part[cityData, #] & /@ tour,
    "TotalDistance" -> totalDistance[tour],
    "TotalCurvature" -> totalCurvature[tour],
    "FinalCost" -> currentCost,
    "FinalH" -> H,
    "Iterations" -> iter
  |> 
];

