parseDigestToRDM[hex_String] := Module[
  {nibbles, v, delta, rho, kappa, weight, phi, flips, a, dNorm, rNorm, kNorm, 
   phaseSigns, P, A, H, i, alpha1 = 1, alpha2 = 0.7, alpha3 = 0.3, 
