  nibbles = IntegerDigits[FromDigits[Characters[hex], 16], 2, 256];
  v = Partition[nibbles, 4];
  v = FromDigits /@ v;

  (* Compute forward deltas *)
  delta = Table[
    Min[Abs[v[[i + 1]] - v[[i]]], 16 - Abs[v[[i + 1]] - v[[i]]]],
    {i, 1, Length[v] - 1}
  ];

  (* Reflection deltas *)
  rho = Table[
    Min[Abs[v[[i]] - v[[65 - i]]], 16 - Abs[v[[i]] - v[[65 - i]]]],
    {i, 1, 32}
  ];

  (* Curvature: second differences *)
  kappa = Table[
    Min[Abs[delta[[i]] - delta[[i - 1]]], 16 - Abs[delta[[i]] - delta[[i - 1]]]],
    {i, 2, Length[delta]}
  ];

  (* Phase sign + parity flips *)
  weight = Total /@ IntegerDigits[v, 2, 4];
  phi = (-1)^weight;
  flips = Table[
    0.5 (1 - phi[[i]] phi[[i + 1]]),
    {i, 1, Length[phi] - 1}
  ];

